-- Written by hand for the held-out set from pterodactyl/panel app/Models (column names as in the models).
CREATE TABLE locations (id serial PRIMARY KEY, short varchar(191) NOT NULL UNIQUE, long text, created_at timestamp, updated_at timestamp);
CREATE TABLE nodes (id serial PRIMARY KEY, uuid char(36) NOT NULL, public boolean NOT NULL, name varchar(191) NOT NULL, description text, location_id int NOT NULL REFERENCES locations(id), fqdn varchar(191) NOT NULL, scheme varchar(191) NOT NULL, behind_proxy boolean NOT NULL, maintenance_mode boolean NOT NULL, memory int NOT NULL, memory_overallocate int NOT NULL, disk int NOT NULL, disk_overallocate int NOT NULL, upload_size int NOT NULL, "daemonListen" smallint NOT NULL, "daemonSFTP" smallint NOT NULL, "daemonBase" varchar(191) NOT NULL, created_at timestamp, updated_at timestamp);
CREATE TABLE users (id serial PRIMARY KEY, username varchar(191) NOT NULL, email varchar(191) NOT NULL);
CREATE TABLE servers (id serial PRIMARY KEY, external_id varchar(191) UNIQUE, uuid char(36) NOT NULL, node_id int NOT NULL REFERENCES nodes(id), name varchar(191) NOT NULL, description text NOT NULL, status varchar(191), skip_scripts boolean NOT NULL, owner_id int NOT NULL REFERENCES users(id), memory int NOT NULL, swap int NOT NULL, disk int NOT NULL, io int NOT NULL, cpu int NOT NULL, threads varchar(191), oom_disabled boolean NOT NULL, allocation_id int NOT NULL, nest_id int NOT NULL, egg_id int NOT NULL, startup text NOT NULL, image varchar(191) NOT NULL, allocation_limit int, database_limit int, backup_limit int NOT NULL, created_at timestamp, updated_at timestamp, installed_at timestamp);
CREATE TABLE allocations (id serial PRIMARY KEY, node_id int NOT NULL REFERENCES nodes(id), ip varchar(191) NOT NULL, ip_alias text, port int NOT NULL, server_id int REFERENCES servers(id), notes varchar(256), created_at timestamp, updated_at timestamp);
CREATE TABLE database_hosts (id serial PRIMARY KEY, name varchar(191) NOT NULL, host varchar(191) NOT NULL, port int NOT NULL);
CREATE TABLE databases (id serial PRIMARY KEY, server_id int NOT NULL REFERENCES servers(id), database_host_id int NOT NULL REFERENCES database_hosts(id), database varchar(191) NOT NULL, username varchar(191) NOT NULL, remote varchar(191) NOT NULL, password text NOT NULL, max_connections int, created_at timestamp, updated_at timestamp);
CREATE TABLE schedules (id serial PRIMARY KEY, server_id int NOT NULL REFERENCES servers(id), name varchar(191) NOT NULL, cron_day_of_week varchar(191) NOT NULL, cron_month varchar(191) NOT NULL, cron_day_of_month varchar(191) NOT NULL, cron_hour varchar(191) NOT NULL, cron_minute varchar(191) NOT NULL, is_active boolean NOT NULL, is_processing boolean NOT NULL, only_when_online boolean NOT NULL, last_run_at timestamp, next_run_at timestamp, created_at timestamp, updated_at timestamp);
